// Original malloc core composed with small-malloc gate and new-handler dispatcher. No new address credit. Normal no-exception domain; physical heap target remains cached in outer body.
using System;namespace Recovered.Gameplay {public static class PtlMallocChildrenCPU {public static uint Allocate(SoundSetupImage m,uint size,Func<SoundSetupImage,uint,uint[],uint> leaf){Func<SoundSetupImage,uint,uint[],uint> route=null;route=delegate(SoundSetupImage image,uint address,uint[] args){if(address==0x6e74ac)return PtlSmallMalloc.Allocate(image,args[0],route);if(address==0x6f2905)return PtlNewHandler.Invoke(image,args[0],route);return leaf(image,address,args);};return PtlMallocCore.Allocate(m,size,route);}}}